79	  /**
80	   * Fetches Pair of partition path and {@link HoodieBaseFile}s for interested partitions.
81	   *
82	   * @param partition   Partition of interest
83	   * @param hoodieTable Instance of {@link HoodieTable} of interest
84	   * @return the list of {@link HoodieBaseFile}
85	   */
86	  public static List<HoodieBaseFile> getLatestBaseFilesForPartition(String partition,
87	                                                                    HoodieTable hoodieTable) {
88	    Option<HoodieInstant> latestCommitTime = hoodieTable.getMetaClient().getCommitsTimeline()
89	        .filterCompletedInstants().lastInstant();
90	    if (latestCommitTime.isPresent()) {
91	      return hoodieTable.getBaseFileOnlyView()
92	          .getLatestBaseFilesBeforeOrOn(partition, latestCommitTime.get().getTimestamp())
93	          .collect(toList());
94	    }
95	    return Collections.emptyList();
96	  }
