193	  public void buildFunctionalIndexDefinition(String indexMetaPath,
194	                                             String indexName,
195	                                             String indexType,
196	                                             Map<String, Map<String, String>> columns,
197	                                             Map<String, String> options) {
198	    ValidationUtils.checkState(
199	        !functionalIndexMetadata.isPresent() || !functionalIndexMetadata.get().getIndexDefinitions().containsKey(indexName),
200	        "Functional index metadata is already present");
201	    List<String> columnNames = new ArrayList<>(columns.keySet());
202	    HoodieFunctionalIndexDefinition functionalIndexDefinition = new HoodieFunctionalIndexDefinition(indexName, indexType, options.get("func"), columnNames, options);
203	    if (functionalIndexMetadata.isPresent()) {
204	      functionalIndexMetadata.get().getIndexDefinitions().put(indexName, functionalIndexDefinition);
205	    } else {
206	      functionalIndexMetadata = Option.of(new HoodieFunctionalIndexMetadata(Collections.singletonMap(indexName, functionalIndexDefinition)));
207	    }
208	    try {
209	      FileIOUtils.createFileInPath(storage, new StoragePath(indexMetaPath), Option.of(getUTF8Bytes(functionalIndexMetadata.get().toJson())));
210	    } catch (IOException e) {
211	      throw new HoodieIOException("Could not write functional index metadata at path: " + indexMetaPath, e);
212	    }
213	  }
