52	    Mockito.when(metaClient.getFunctionalIndexMetadata()).thenReturn(Option.empty());
53	    HoodieMetadataConfig.Builder metadataConfigBuilder = HoodieMetadataConfig.newBuilder();
54	    int expectedEnabledPartitions;
55	    switch (partitionType) {
56	      case FILES:
57	      case FUNCTIONAL_INDEX:
