78	        throw new IllegalArgumentException("Unknown partition type: " + partitionType);
79	    }
80	
81	    List<MetadataPartitionType> enabledPartitions = MetadataPartitionType.getEnabledPartitions(metadataConfigBuilder.build().getProps(), metaClient);
82	
83	    // Verify partition type is enabled due to config
